            (void)(m_assertIn(Args{SV("zombie"), pvz::getattr(pvz::getattr(L_b, SY("zsecrets")), SY("trinity"))}));
            L_native = py_dict({{SV("血量"), V(50.0)}, {SV("_pvp_max_hp"), V(50.0)}, {SV("移速"), V(1.0)}, {SV("_pvp_seat"), SV("zombie")}});
